        &owner.identity,
        new_channel_id(),
        1,
        vec![],
        1,
        1,
        EventKind::MembershipChange,
        ChannelMeta {
            name: "Account-target owner fixture".into(),
            members: nodes.iter().map(|node| node.identity.public()).collect(),
            epoch: 0,
            owner: owner.user_id(),
        }
        .encode(),
    );
    for node in &nodes {
        install(node, &genesis);
