        owner.record_channel_owner_origin(group).unwrap();
        let mut work =
            crate::node::channel_account_maintenance::ChannelAccountMaintenance::default();
        for _ in 0..12 {
            owner.maintain_account_channels(&mut work).await;
            if owner
