    pub(in crate::node) fn install_batch_on(
        c: &Connection,
        candidate: &PreparedChannelReceive,
        role: ChannelReceptionRole,
        metadata: &ReceptionMetadata,
    ) -> Result<(), LogError> {
        if active_account_on(c)? != candidate.account {
            return Err(LogError::StaleCursor);
        }
