pub(super) struct StreamState {
    pub head: ReceptionCursor,
    pub retired: u64,
}

pub(super) fn active_account_on(c: &Connection) -> Result<[u8; 32], LogError> {
    c.query_row(
        "SELECT account FROM participant_profile WHERE singleton=1",
        [],
