    }
    fn pending(c: &Connection) {
        c.execute(
            "INSERT INTO retained_events VALUES(?1,?2)",
            params![[1u8; 16].as_slice(), [3u8; 32].as_slice()],
        )
        .unwrap();
        c.execute(
            "INSERT INTO pending_ingress_origins VALUES(?1,?2,?3,?4,3,?5)",
            params![
                [4u8; 32].as_slice(),
